#!/usr/bin/env python3
"""One-shot fixup for crash-safe dispatch and stale-operation reconciliation."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOTNET = ROOT / "skills/mcp-steward-architect/tools/steward-templates/dotnet/StewardSeedRuntime.cs.template"
PYTHON = ROOT / "skills/mcp-steward-architect/tools/steward-templates/python/steward_runtime.py.template"
PYTHON_TEST = ROOT / "skills/mcp-steward-architect/tools/steward-templates/python/test_steward_runtime.py.template"
SMOKE = ROOT / "skills/mcp-steward-architect/tools/steward-templates/dotnet/SmokeProgram.cs.template"


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"expected one match in {path}: {old[:100]!r}; got {count}")
    path.write_text(text.replace(old, new), encoding="utf-8", newline="\n")


def replace_between(path: Path, start: str, end: str, replacement: str) -> None:
    text = path.read_text(encoding="utf-8")
    begin = text.find(start)
    if begin < 0:
        raise RuntimeError(f"start marker missing in {path}: {start!r}")
    finish = text.find(end, begin)
    if finish < 0:
        raise RuntimeError(f"end marker missing in {path}: {end!r}")
    path.write_text(text[:begin] + replacement + text[finish:], encoding="utf-8", newline="\n")


def patch_dotnet() -> None:
    # A reserved operation is definitely not delivered. If superseded before dispatch starts,
    # make that fact terminal so it cannot block the successor.
    replace_once(
        DOTNET,
        '''                _state.Jobs[previousJob.JobId] = previousJob;\n                AuditLocked(previousJob.JobId, "superseded", new Dictionary<string, string>\n''',
        '''                _state.Jobs[previousJob.JobId] = previousJob;\n                foreach (var operationRef in previousJob.ExternalOperationRefs)\n                {\n                    if (_state.Operations.TryGetValue(operationRef, out var previousOperation) &&\n                        previousOperation.State == "reserved" &&\n                        previousOperation.Delivery == "not-delivered")\n                    {\n                        _state.Operations[operationRef] = previousOperation with\n                        {\n                            State = "abandoned",\n                            ObservedAt = now,\n                        };\n                    }\n                }\n                AuditLocked(previousJob.JobId, "superseded", new Dictionary<string, string>\n''',
    )

    run_one_due = '''    public bool RunOneDue()\n    {\n        SeedAction? action = null;\n        lock (_gate)\n        {\n            var staleOperation = NextSupersededOperationLocked();\n            if (staleOperation is not null)\n            {\n                var staleJob = CurrentJobLocked(staleOperation.JobId);\n                action = new(\n                    staleOperation.Delivery == "delivery-unknown" ? "stale-reconcile" : "stale-poll",\n                    staleJob,\n                    staleOperation);\n            }\n            else\n            {\n                var job = NextJobLocked();\n                if (job is null)\n                    return false;\n                if (job.Cancellation == "requested")\n                {\n                    _state.Jobs[job.JobId] = job with\n                    {\n                        Version = job.Version + 1,\n                        Status = "cancelled",\n                        Stage = "cancelled",\n                        Cancellation = "completed",\n                        UpdatedAt = _clock.UtcNow,\n                    };\n                    AuditLocked(job.JobId, "cancelled", new Dictionary<string, string>());\n                    SaveLocked();\n                    return true;\n                }\n                var operation = _state.Operations.Values\n                    .FirstOrDefault(item => item.JobId == job.JobId);\n                if (operation is null)\n                {\n                    ReserveExternalLocked(job);\n                    _faults.Trip("after-reservation");\n                    SaveLocked();\n                    return true;\n                }\n                if (operation.Delivery == "not-delivered")\n                {\n                    BeginDispatchLocked(operation.OperationId);\n                    SaveLocked();\n                    action = new("dispatch", job, _state.Operations[operation.OperationId]);\n                }\n                else if (operation.Delivery == "delivery-unknown")\n                    action = new("reconcile", job, operation);\n                else if (!_state.Evidence.Values.Any(item => item.JobId == job.JobId))\n                    action = new("poll", job, operation);\n                else\n                {\n                    FinalizeLocked(job);\n                    SaveLocked();\n                    return true;\n                }\n            }\n        }\n\n        if (action.Kind == "dispatch")\n        {\n            if (_faults.Trip("after-dispatch-start"))\n                return true;\n            var handle = _provider.Dispatch(action.Operation.OperationId, action.Job.Subject);\n            if (_faults.Trip("after-dispatch") || _faults.Trip("before-handle-persist"))\n                return true;\n            lock (_gate)\n            {\n                ApplyDispatchLocked(action.Operation.OperationId, handle);\n                SaveLocked();\n            }\n            return true;\n        }\n        if (action.Kind is "reconcile" or "stale-reconcile")\n        {\n            var handle = _provider.Reconcile(action.Operation.OperationId, action.Job.Subject);\n            lock (_gate)\n            {\n                ApplyReconcileLocked(action.Operation.OperationId, handle);\n                SaveLocked();\n            }\n            return true;\n        }\n\n        var result = _provider.Poll(action.Operation.RemoteHandle!, action.Job.Subject);\n        if (!result.Completed)\n            return false;\n        lock (_gate)\n        {\n            if (action.Kind == "stale-poll")\n            {\n                MarkOperationObservedLocked(action.Operation.OperationId);\n                AuditLocked(action.Job.JobId, "late-result-discarded", new Dictionary<string, string>\n                {\n                    ["operationId"] = action.Operation.OperationId,\n                });\n                SaveLocked();\n                return true;\n            }\n            RequireCurrentLocked(action.Job);\n            if (_faults.Trip("before-result-persist"))\n                return true;\n            MarkOperationObservedLocked(action.Operation.OperationId);\n            PersistEvidenceLocked(action.Job, result.Payload);\n            SaveLocked();\n        }\n        return true;\n    }\n\n'''
    replace_between(DOTNET, "    public bool RunOneDue()\n", "    public void RecoverUntilIdle", run_one_due)

    recover = '''    public void RecoverUntilIdle(int maxSteps = 100)\n    {\n        for (var step = 0; step < maxSteps; step++)\n        {\n            if (!RunOneDue())\n                return;\n            lock (_gate)\n            {\n                if (NextJobLocked() is null && NextSupersededOperationLocked() is null)\n                    return;\n            }\n        }\n        throw new InvalidOperationException("recovery supervisor exceeded bounded step budget");\n    }\n\n'''
    replace_between(DOTNET, "    public void RecoverUntilIdle", "    public static bool VerifyHandoffDigest", recover)

    dispatch_helpers = '''    private void BeginDispatchLocked(string operationId)\n    {\n        var operation = _state.Operations[operationId];\n        var job = CurrentJobLocked(operation.JobId);\n        RequireCurrentLocked(job);\n        var now = _clock.UtcNow;\n        _state.Operations[operationId] = operation with\n        {\n            State = "dispatching",\n            Delivery = "delivery-unknown",\n            RetryDisposition = "reconcile-first",\n            ObservedAt = now,\n        };\n        _state.Jobs[job.JobId] = job with\n        {\n            Version = job.Version + 1,\n            Status = "reconciling",\n            Stage = "dispatch-started",\n            UpdatedAt = now,\n        };\n        AuditLocked(job.JobId, "dispatch-started", new Dictionary<string, string>\n        {\n            ["operationId"] = operationId,\n        });\n    }\n\n    private void ApplyDispatchLocked(string operationId, string remoteHandle)\n    {\n        var operation = _state.Operations[operationId];\n        var job = CurrentJobLocked(operation.JobId);\n        var now = _clock.UtcNow;\n        _state.Operations[operationId] = operation with\n        {\n            State = "dispatched",\n            Delivery = "delivered",\n            RetryDisposition = "forbidden",\n            RemoteHandle = remoteHandle,\n            ObservedAt = now,\n        };\n        if (IsCurrentLocked(job) && !Terminal.Contains(job.Status))\n        {\n            _state.Jobs[job.JobId] = job with\n            {\n                Version = job.Version + 1,\n                Status = "waiting-external",\n                Stage = "external-dispatched",\n                UpdatedAt = now,\n            };\n        }\n        AuditLocked(job.JobId, IsCurrentLocked(job) ? "external-dispatched" : "late-dispatch-observed",\n            new Dictionary<string, string>\n            {\n                ["delivery"] = "delivered",\n                ["operationId"] = operationId,\n            });\n    }\n\n    private void ApplyReconcileLocked(string operationId, string remoteHandle)\n    {\n        var operation = _state.Operations[operationId];\n        var job = CurrentJobLocked(operation.JobId);\n        var now = _clock.UtcNow;\n        _state.Operations[operationId] = operation with\n        {\n            State = "dispatched",\n            Delivery = "delivered",\n            RetryDisposition = "forbidden",\n            RemoteHandle = remoteHandle,\n            ObservedAt = now,\n            ReconcileCount = operation.ReconcileCount + 1,\n        };\n        if (IsCurrentLocked(job) && !Terminal.Contains(job.Status))\n        {\n            _state.Jobs[job.JobId] = job with\n            {\n                Version = job.Version + 1,\n                Status = "waiting-external",\n                Stage = "reconciled",\n                UpdatedAt = now,\n            };\n        }\n        AuditLocked(job.JobId, "reconciled", new Dictionary<string, string>\n        {\n            ["operationId"] = operationId,\n        });\n    }\n\n    private void MarkOperationObservedLocked(string operationId)\n    {\n        var operation = _state.Operations[operationId];\n        _state.Operations[operationId] = operation with\n        {\n            State = "observed",\n            ObservedAt = _clock.UtcNow,\n        };\n    }\n\n'''
    replace_between(DOTNET, "    private void ApplyDispatchLocked", "    private void PersistEvidenceLocked", dispatch_helpers)

    # Completion must account for unresolved predecessor side effects in the same lineage, not just this job.
    replace_once(
        DOTNET,
        '''        var ambiguous = _state.Operations.Values\n            .Where(item => item.JobId == job.JobId && item.Delivery == "delivery-unknown")\n            .Select(item => item.OperationId)\n''',
        '''        var ambiguous = _state.Operations.Values\n            .Where(item =>\n                _state.Jobs.TryGetValue(item.JobId, out var operationJob) &&\n                operationJob.LineageId == job.LineageId &&\n                item.State != "observed" &&\n                item.State != "abandoned")\n            .Select(item => item.OperationId)\n''',
    )

    helpers = '''    private StewardOperation? NextSupersededOperationLocked() =>\n        _state.Operations.Values\n            .Where(item =>\n                _state.Jobs.TryGetValue(item.JobId, out var job) &&\n                job.Status == "superseded" &&\n                item.State != "observed" &&\n                item.State != "abandoned" &&\n                (item.Delivery == "delivery-unknown" || item.Delivery == "delivered"))\n            .OrderBy(item => item.ObservedAt)\n            .ThenBy(item => item.OperationId, StringComparer.Ordinal)\n            .FirstOrDefault();\n\n    private bool IsCurrentLocked(StewardSeedJob job) =>\n        _state.Lineages.TryGetValue(job.LineageId, out var lineage) &&\n        lineage.CurrentJobId == job.JobId &&\n        lineage.CurrentGeneration == job.Generation &&\n        CurrentJobLocked(job.JobId).AttemptId == job.AttemptId;\n\n'''
    replace_once(DOTNET, "    private StewardSeedJob CurrentJobLocked(string jobId) =>\n", helpers + "    private StewardSeedJob CurrentJobLocked(string jobId) =>\n")


def patch_python() -> None:
    # Reserved/not-delivered is safe to abandon on supersession; anything after dispatch-start remains recoverable.
    replace_once(
        PYTHON,
        '''                if superseded.rowcount:\n                    self._audit(\n                        db,\n                        previous_job_id,\n                        "superseded",\n                        {"byJobId": job_id, "generation": generation},\n                    )\n''',
        '''                if superseded.rowcount:\n                    db.execute(\n                        "UPDATE external_operations SET state='abandoned',observed_at=? "\n                        "WHERE job_id=? AND state='reserved' AND delivery='not-delivered'",\n                        (now, previous_job_id),\n                    )\n                    self._audit(\n                        db,\n                        previous_job_id,\n                        "superseded",\n                        {"byJobId": job_id, "generation": generation},\n                    )\n''',
    )

    methods = '''    def _is_current_tx(self, db: sqlite3.Connection, job_id: str, generation: int) -> bool:\n        row = db.execute(\n            "SELECT j.status,l.current_job_id,l.current_generation FROM steward_jobs j "\n            "JOIN steward_lineages l ON l.lineage_id=j.lineage_id WHERE j.job_id=?",\n            (job_id,),\n        ).fetchone()\n        return bool(\n            row is not None\n            and row["status"] not in _TERMINAL\n            and str(row["current_job_id"]) == job_id\n            and int(row["current_generation"]) == generation\n        )\n\n    def begin_dispatch(self, operation_id: str) -> None:\n        now = _iso(self.clock.now())\n        with self._write() as db:\n            row = db.execute(\n                "SELECT job_id,generation FROM external_operations WHERE operation_id=?",\n                (operation_id,),\n            ).fetchone()\n            if row is None:\n                raise KeyError(operation_id)\n            job_id, generation = str(row["job_id"]), int(row["generation"])\n            if not self._is_current_tx(db, job_id, generation):\n                raise RuntimeError("stale lineage dispatch")\n            db.execute(\n                "UPDATE external_operations SET state='dispatching',delivery='delivery-unknown',"\n                "retry_disposition='reconcile-first',observed_at=? WHERE operation_id=?",\n                (now, operation_id),\n            )\n            db.execute(\n                "UPDATE steward_jobs SET status='reconciling',stage='dispatch-started',version=version+1,updated_at=? "\n                "WHERE job_id=?",\n                (now, job_id),\n            )\n            self._audit(db, job_id, "dispatch-started", {"operationId": operation_id})\n\n    def record_dispatch(self, operation_id: str, remote_handle: str) -> None:\n        now = _iso(self.clock.now())\n        with self._write() as db:\n            row = db.execute(\n                "SELECT job_id,generation FROM external_operations WHERE operation_id=?",\n                (operation_id,),\n            ).fetchone()\n            if row is None:\n                raise KeyError(operation_id)\n            job_id, generation = str(row["job_id"]), int(row["generation"])\n            db.execute(\n                "UPDATE external_operations SET state='dispatched',delivery='delivered',retry_disposition='forbidden',"\n                "remote_handle=?,observed_at=? WHERE operation_id=?",\n                (remote_handle, now, operation_id),\n            )\n            current = self._is_current_tx(db, job_id, generation)\n            if current:\n                db.execute(\n                    "UPDATE steward_jobs SET status='waiting-external',stage='external-dispatched',"\n                    "version=version+1,updated_at=? WHERE job_id=?",\n                    (now, job_id),\n                )\n            self._audit(\n                db,\n                job_id,\n                "external-dispatched" if current else "late-dispatch-observed",\n                {"delivery": "delivered", "operationId": operation_id},\n            )\n\n    def reconcile(self, operation_id: str, remote_handle: str) -> None:\n        now = _iso(self.clock.now())\n        with self._write() as db:\n            row = db.execute(\n                "SELECT job_id,generation FROM external_operations WHERE operation_id=?",\n                (operation_id,),\n            ).fetchone()\n            if row is None:\n                raise KeyError(operation_id)\n            job_id, generation = str(row["job_id"]), int(row["generation"])\n            db.execute(\n                "UPDATE external_operations SET state='dispatched',delivery='delivered',retry_disposition='forbidden',"\n                "remote_handle=?,observed_at=?,reconcile_count=reconcile_count+1 WHERE operation_id=?",\n                (remote_handle, now, operation_id),\n            )\n            if self._is_current_tx(db, job_id, generation):\n                db.execute(\n                    "UPDATE steward_jobs SET status='waiting-external',stage='reconciled',version=version+1,updated_at=? "\n                    "WHERE job_id=?",\n                    (now, job_id),\n                )\n            self._audit(db, job_id, "reconciled", {"operationId": operation_id})\n\n    def mark_operation_observed(self, operation_id: str, *, require_current: bool = False) -> None:\n        now = _iso(self.clock.now())\n        with self._write() as db:\n            row = db.execute(\n                "SELECT job_id,generation FROM external_operations WHERE operation_id=?",\n                (operation_id,),\n            ).fetchone()\n            if row is None:\n                raise KeyError(operation_id)\n            if require_current and not self._is_current_tx(db, str(row["job_id"]), int(row["generation"])):\n                raise RuntimeError("stale lineage result")\n            db.execute(\n                "UPDATE external_operations SET state='observed',observed_at=? WHERE operation_id=?",\n                (now, operation_id),\n            )\n\n    def next_superseded_operation(self) -> dict[str, Any] | None:\n        with self._connect() as db:\n            row = db.execute(\n                "SELECT o.* FROM external_operations o JOIN steward_jobs j ON j.job_id=o.job_id "\n                "WHERE j.status='superseded' AND o.state NOT IN ('observed','abandoned') "\n                "AND o.delivery IN ('delivery-unknown','delivered') ORDER BY o.observed_at,o.operation_id LIMIT 1"\n            ).fetchone()\n        return None if row is None else dict(row)\n\n    def unresolved_lineage_operations(self, job_id: str) -> list[str]:\n        with self._connect() as db:\n            rows = db.execute(\n                "SELECT o.operation_id FROM external_operations o "\n                "JOIN steward_jobs owner ON owner.job_id=o.job_id "\n                "JOIN steward_jobs current ON current.job_id=? "\n                "WHERE owner.lineage_id=current.lineage_id AND o.state NOT IN ('observed','abandoned') "\n                "ORDER BY o.operation_id",\n                (job_id,),\n            ).fetchall()\n        return [str(row[0]) for row in rows]\n\n'''
    replace_between(PYTHON, "    def record_dispatch", "    def evidence", methods + "    def evidence")

    # Evidence writes must never resurrect a superseded generation.
    replace_once(
        PYTHON,
        '''        with self._write() as db:\n            db.execute("INSERT INTO steward_evidence VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",\n''',
        '''        with self._write() as db:\n            if not self._is_current_tx(db, job_id, int(job["generation"])):\n                raise RuntimeError("stale lineage evidence")\n            db.execute("INSERT INTO steward_evidence VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",\n''',
    )

    replace_between(
        PYTHON,
        "    def ambiguous(self, job_id: str) -> list[str]:\n",
        "    def save_terminal",
        '''    def ambiguous(self, job_id: str) -> list[str]:\n        return self.unresolved_lineage_operations(job_id)\n\n''',
    )

    # Final publication closes the race again inside the write transaction and checks the whole lineage.
    replace_once(
        PYTHON,
        '''            count = db.execute("SELECT COUNT(*) FROM external_operations WHERE job_id=? AND delivery='delivery-unknown'", (job_id,)).fetchone()[0]\n            if count: raise RuntimeError("completion blocked by ambiguous delivery")\n''',
        '''            count = db.execute(\n                "SELECT COUNT(*) FROM external_operations o JOIN steward_jobs owner ON owner.job_id=o.job_id "\n                "JOIN steward_jobs current ON current.job_id=? "\n                "WHERE owner.lineage_id=current.lineage_id AND o.state NOT IN ('observed','abandoned')",\n                (job_id,),\n            ).fetchone()[0]\n            if count:\n                raise RuntimeError("completion blocked by unresolved lineage operation")\n''',
    )

    # The gate reports all unresolved side effects for the lineage, including predecessors.
    replace_once(
        PYTHON,
        '''        obligations, blocked = [], bool(self.store.ambiguous(job_id))\n''',
        '''        unresolved = self.store.unresolved_lineage_operations(job_id)\n        obligations, blocked = [], bool(unresolved)\n''',
    )
    replace_once(
        PYTHON,
        '''                "obligations":obligations,"ambiguousOperationRefs":self.store.ambiguous(job_id),"evaluatedAt":_iso(now)}\n''',
        '''                "obligations":obligations,"ambiguousOperationRefs":unresolved,"evaluatedAt":_iso(now)}\n''',
    )

    run_once = '''    def run_once(self) -> bool:\n        stale_operation = self.store.next_superseded_operation()\n        if stale_operation is not None:\n            stale_job = self.store.job(str(stale_operation["job_id"]))\n            operation_id = str(stale_operation["operation_id"])\n            if stale_operation["delivery"] == "delivery-unknown":\n                handle = self.provider.reconcile(operation_id, stale_job["subject"])\n                self.store.reconcile(operation_id, handle)\n                return True\n            payload = self.provider.poll(str(stale_operation["remote_handle"]), stale_job["subject"])\n            if payload.get("state") != "completed":\n                return False\n            self.store.mark_operation_observed(operation_id)\n            return True\n\n        job=self.store.next_job()\n        if job is None: return False\n        if job["cancellation"]=="requested": self.store.finish_cancel(job["jobId"]); return True\n        operation=self.store.operation_for_job(job["jobId"])\n        if operation is None:\n            self.store.reserve_external(job["jobId"])\n            self.faults.trip("after-reservation")\n            return True\n        operation_id = str(operation["operation_id"])\n        if operation["delivery"]=="not-delivered":\n            self.store.begin_dispatch(operation_id)\n            if self.faults.trip("after-dispatch-start"):\n                return True\n            handle=self.provider.dispatch(operation_id,job["subject"])\n            if self.faults.trip("after-dispatch") or self.faults.trip("before-handle-persist"):\n                return True\n            self.store.record_dispatch(operation_id,handle)\n            return True\n        if operation["delivery"]=="delivery-unknown":\n            self.store.reconcile(operation_id,self.provider.reconcile(operation_id,job["subject"])); return True\n        if not self.store.evidence(job["jobId"]):\n            payload=self.provider.poll(str(operation["remote_handle"]),job["subject"])\n            if payload.get("state")!="completed": return False\n            if self.faults.trip("before-result-persist"): return True\n            self.store.mark_operation_observed(operation_id, require_current=True)\n            for req in self.profile["completion"]["obligations"]:\n                criterion=self._criterion(req["id"])\n                if criterion.get("approved_producers") and self.provider.producer_id not in criterion["approved_producers"]: continue\n                self.store.persist_evidence(job["jobId"],req,criterion,self.provider.producer_id,payload,self.recipe_id)\n            return True\n        self.finalize_with_gate(job["jobId"]); return True\n\n    def recover_until_idle(self, max_steps: int = 100) -> None:\n        for _ in range(max_steps):\n            if not self.run_once():\n                return\n            if self.store.next_job() is None and self.store.next_superseded_operation() is None:\n                return\n        raise RuntimeError("recovery supervisor exceeded bounded step budget")\n\n'''
    replace_between(PYTHON, "    def run_once(self) -> bool:\n", "    def start_background", run_once)


def patch_tests() -> None:
    # The crash-before-I/O test proves durable dispatch-start converts a possible side effect into reconciliation.
    extra_python = '''\n\nclass _CountingProvider:\n    producer_id = "seed-provider"\n\n    def __init__(self) -> None:\n        self.dispatch_count = 0\n        self.reconcile_count = 0\n\n    def dispatch(self, operation_id: str, subject: dict[str, object]) -> str:\n        self.dispatch_count += 1\n        return f"remote-{operation_id}"\n\n    def reconcile(self, operation_id: str, subject: dict[str, object]) -> str:\n        self.reconcile_count += 1\n        return f"remote-{operation_id}"\n\n    def poll(self, remote_handle: str, subject: dict[str, object]) -> dict[str, object]:\n        return {"state": "completed", "remoteHandle": remote_handle, "subject": subject}\n\n\ndef test_dispatch_start_is_durable_before_remote_io(tmp_path: Path) -> None:\n    profile, proof = _policy()\n    provider = _CountingProvider()\n    state_path = tmp_path / "dispatch-start.db"\n    clock = FakeClock(datetime(2026, 1, 1, tzinfo=UTC))\n    first = StewardRuntime(\n        StewardStore(state_path, clock),\n        profile,\n        proof,\n        provider=provider,\n        faults=FaultInjector({"after-dispatch-start"}),\n    )\n    admitted = first.submit("repo-3", "abc", "dispatch-start-1")\n    first.run_once()\n    first.run_once()\n    assert provider.dispatch_count == 0\n    assert first.status(admitted["jobId"])["status"] == "reconciling"\n\n    recovered = StewardRuntime(StewardStore(state_path, clock), profile, proof, provider=provider)\n    recovered.recover_until_idle()\n    assert provider.dispatch_count == 0\n    assert provider.reconcile_count >= 1\n    assert recovered.status(admitted["jobId"])["status"] == "completed"\n'''
    text = PYTHON_TEST.read_text(encoding="utf-8")
    if "test_dispatch_start_is_durable_before_remote_io" not in text:
        PYTHON_TEST.write_text(text.rstrip() + extra_python + "\n", encoding="utf-8", newline="\n")

    # Extend .NET smoke with a deterministic no-dispatch-after-crash proof.
    replace_once(
        SMOKE,
        '''        using (var current = new StewardSeedRuntime(\n            Path.Combine(root, "supersession"),\n''',
        '''        var countingProvider = new CountingSeedProvider();\n        var dispatchStartRoot = Path.Combine(root, "dispatch-start");\n        using (var beforeDispatch = new StewardSeedRuntime(\n            dispatchStartRoot,\n            clock,\n            countingProvider,\n            new SeedFaultInjector(["after-dispatch-start"]),\n            profile,\n            proof))\n        {\n            var pending = beforeDispatch.Submit("repo-3", "abc", "dispatch-start-1");\n            beforeDispatch.RunOneDue();\n            beforeDispatch.RunOneDue();\n            if (countingProvider.DispatchCount != 0 || beforeDispatch.Status(pending.JobId).Status != "reconciling")\n                throw new InvalidOperationException("Dispatch start was not persisted before remote I/O.");\n        }\n        using (var recoveredBeforeDispatch = new StewardSeedRuntime(\n            dispatchStartRoot,\n            clock,\n            countingProvider,\n            new SeedFaultInjector(),\n            profile,\n            proof))\n        {\n            recoveredBeforeDispatch.RecoverUntilIdle();\n            if (countingProvider.DispatchCount != 0 || countingProvider.ReconcileCount == 0)\n                throw new InvalidOperationException("Recovery replayed a dispatch instead of reconciling durable ambiguity.");\n        }\n\n        using (var current = new StewardSeedRuntime(\n            Path.Combine(root, "supersession"),\n''',
    )
    smoke = SMOKE.read_text(encoding="utf-8")
